//! Limited Access has no inventory mutation, restore, AI, export or arbitrary SQL command.
use reqwest::{blocking::Client,redirect::Policy,Url};
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,io::Write,path::{Path,PathBuf},time::{Duration,Instant}};
use uuid::Uuid;
const SERVICE:&str="com.repaircenter.inventorymanager.limitedaccess";
pub const PRODUCTS_SQL:&str="SELECT p.id,p.item_code,p.name,p.model_description,b.quantity FROM products p JOIN product_balances b ON b.product_id=p.id ORDER BY p.name,p.item_code";
pub const LINES_SQL:&str="SELECT * FROM (SELECT l.id,l.product_id,s.created_at,CASE WHEN d.purpose IN ('personal','damage') THEN NULL ELSE s.cr_number END AS cr_number,p.name AS product_name,p.item_code,p.model_description,l.quantity,l.unit_price_baisa,COALESCE(d.purpose,'sale') AS purpose,COALESCE((SELECT json_extract(w.record_json,'$.original_cr') FROM legacy_archive w WHERE w.kind='warranty_link' AND json_extract(w.record_json,'$.replacement_line_id')=l.id LIMIT 1),'') AS original_cr FROM sale_lines l JOIN sales s ON s.id=l.sale_id JOIN products p ON p.id=l.product_id LEFT JOIN stock_out_details d ON d.line_id=l.id UNION ALL SELECT 'return:'||r.id AS id,l.product_id,r.resolved_at AS created_at,s.cr_number,p.name||' - '||r.resolution||' settlement ('||r.quantity||' returned)' AS product_name,p.item_code,p.model_description,0 AS quantity,NULL AS unit_price_baisa,'return_settlement' AS purpose,'' AS original_cr FROM damaged_returns r JOIN sale_lines l ON l.id=r.line_id JOIN sales s ON s.id=l.sale_id JOIN products p ON p.id=l.product_id WHERE r.resolved_at IS NOT NULL) ORDER BY created_at DESC,id DESC";
pub const ENTRIES_SQL:&str="SELECT e.id,e.product_id,p.item_code,p.name AS product_name,e.created_at,e.quantity,b.remaining_quantity FROM stock_entries e JOIN products p ON p.id=e.product_id JOIN entry_balances b ON b.id=e.id ORDER BY e.created_at DESC,e.rowid DESC";
const STATE_SQL:&str="SELECT key,value FROM migration_info WHERE key IN ('online_epoch','online_revision') ORDER BY key";
#[derive(Clone,Serialize,Deserialize)] struct Configuration{url:String,credential_id:String}
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq)] #[serde(deny_unknown_fields)] pub struct Product{pub id:String,pub item_code:String,pub name:String,pub model_description:String,pub quantity:i64}
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq)] #[serde(deny_unknown_fields)] pub struct Line{pub id:String,pub product_id:String,pub created_at:String,pub cr_number:Option<String>,pub product_name:String,pub item_code:String,pub model_description:String,pub quantity:i64,pub unit_price_baisa:Option<i64>,pub purpose:String,pub original_cr:String}
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq)] #[serde(deny_unknown_fields)] pub struct Entry{pub id:String,pub product_id:String,pub item_code:String,pub product_name:String,pub created_at:String,pub quantity:i64,pub remaining_quantity:i64}
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq)] #[serde(deny_unknown_fields)] pub struct Snapshot{pub products:Vec<Product>,pub sale_lines:Vec<Line>,pub entries:Vec<Entry>,pub updated_at:String}
#[derive(Serialize,Deserialize)] #[serde(deny_unknown_fields)] struct Saved{url:Option<String>,state:Value,snapshot:Snapshot}
pub struct Backend{client:Client,config:Option<Configuration>,directory:PathBuf,saved:Saved,verified:Option<Instant>,warning:String}
fn atomic(path:&Path,bytes:&[u8])->Result<(),String>{let temporary=path.with_extension(format!("{}.tmp",Uuid::new_v4()));let mut file=fs::OpenOptions::new().create_new(true).write(true).open(&temporary).map_err(|_|"Cannot create a local read-only snapshot.")?;file.write_all(bytes).and_then(|_|file.sync_all()).map_err(|_|"Cannot save the local snapshot.")?;drop(file);fs::rename(temporary,path).map_err(|_|"Cannot complete the local snapshot.".into())}
fn endpoint(input:&str)->Result<String,String>{let text=input.trim().replacen("libsql://","https://",1);let url=Url::parse(&text).map_err(|_|"Enter the existing Turso database URL.")?;if url.scheme()!="https"||!url.host_str().is_some_and(|h|h.ends_with(".turso.io"))||url.path()!="/"||url.query().is_some()||url.fragment().is_some()||!url.username().is_empty()||url.password().is_some(){return Err("Use the same libsql:// database address as the full application.".into());}Ok(url.as_str().trim_end_matches('/').to_string())}
fn credential(c:&Configuration)->Result<String,String>{keyring::Entry::new(SERVICE,&c.credential_id).map_err(|_|"Secure credential storage unavailable.")?.get_password().map_err(|_|"Enter the existing database key in Connection settings.".into())}
fn statement(sql:&str)->Value{json!({"sql":sql,"args":[],"want_rows":true})}
fn read(client:&Client,url:&str,token:&str,sql:&[&str])->Result<Vec<Value>,String>{
 if sql.iter().any(|s|!["BEGIN","COMMIT",STATE_SQL,PRODUCTS_SQL,LINES_SQL,ENTRIES_SQL].contains(s)){return Err("Limited Access permits only its fixed read-only queries.".into());}
 let steps=sql.iter().enumerate().map(|(i,s)|{let mut step=json!({"stmt":statement(s)});if i>0{step["condition"]=json!({"type":"ok","step":i-1});}step}).collect::<Vec<_>>();
 let response=client.post(format!("{url}/v2/pipeline")).bearer_auth(token).json(&json!({"requests":[{"type":"batch","batch":{"steps":steps}},{"type":"close"}]})).send().map_err(|_|"Online refresh unavailable. Showing the last saved read-only copy; no records were changed.".to_string())?;
 if !response.status().is_success(){return Err(format!("Connection rejected (HTTP {}). Check the existing database address and key.",response.status().as_u16()));}
 use std::io::Read;let mut bytes=Vec::new();response.take(16*1024*1024+1).read_to_end(&mut bytes).map_err(|_|"Online response interrupted.")?;if bytes.len()>16*1024*1024{return Err("Read-only response exceeds the supported size.".into());}
 let value:Value=serde_json::from_slice(&bytes).map_err(|_|"Invalid online response.")?;let result=&value["results"][0];if result["type"]!="ok"{return Err("The online database could not be read.".into());}
 let result=&result["response"]["result"];if result["step_errors"].as_array().is_none_or(|errors|errors.iter().any(|e|!e.is_null())){return Err("The database is unavailable or incompatible with this read-only copy. No records were changed.".into());}let rows=result["step_results"].as_array().ok_or("Incomplete online response.")?;if rows.len()!=sql.len()||rows.iter().any(Value::is_null){return Err("Incomplete online response.".into());}Ok(rows.clone())
}
fn projected<T:serde::de::DeserializeOwned>(result:&Value,columns:&[&str])->Result<Vec<T>,String>{
 let actual=result["cols"].as_array().ok_or("Missing read-only columns.")?;if actual.len()!=columns.len()||actual.iter().zip(columns).any(|(c,n)|c["name"]!=*n){return Err("Unexpected read-only columns.".into());}
 result["rows"].as_array().ok_or("Missing read-only rows.")?.iter().map(|row|{let cells=row.as_array().ok_or("Invalid row.")?;if cells.len()!=columns.len(){return Err("Incomplete row.".into());}let mut object=serde_json::Map::new();for (name,cell) in columns.iter().zip(cells){let v=match cell["type"].as_str(){Some("text")=>json!(cell["value"].as_str().ok_or("Invalid text.")?),Some("integer")=>json!(cell["value"].as_str().ok_or("Invalid number.")?.parse::<i64>().map_err(|_|"Invalid number.")?),Some("null")=>Value::Null,_=>return Err("Unsupported read-only value.".into())};object.insert(name.to_string(),v);}serde_json::from_value(json!(object)).map_err(|_|"Invalid read-only data.".into())}).collect()
}
fn state(result:&Value)->Result<Value,String>{let mut state=serde_json::Map::new();for row in result["rows"].as_array().ok_or("Missing database state.")?{let name=row[0]["value"].as_str().ok_or("Invalid database state.")?;let value=row[1]["value"].as_str().ok_or("Invalid database state.")?;if name=="online_epoch"{Uuid::parse_str(value).map_err(|_|"Invalid online epoch.")?;state.insert("epoch".into(),json!(value));}else if name=="online_revision"{state.insert("revision".into(),json!(value.parse::<u64>().map_err(|_|"Invalid online revision.")?));}}if state.len()!=2{return Err("Open the full application and initialize its online connection first.".into());}Ok(json!(state))}
impl Backend{
 pub fn open(directory:&Path,seed:&Path)->Result<Self,String>{fs::create_dir_all(directory).map_err(|_|"Cannot initialize the Limited Access data folder.")?;let config:Option<Configuration>=fs::read(directory.join("connection.json")).ok().map(|b|serde_json::from_slice(&b).map_err(|_|"Invalid Limited Access connection settings.")).transpose()?;
  let mut saved=fs::read(directory.join("snapshot.json")).ok().and_then(|b|serde_json::from_slice::<Saved>(&b).ok()).or_else(||fs::read(seed).ok().and_then(|b|serde_json::from_slice::<Snapshot>(&b).ok()).map(|snapshot|Saved{url:Some("libsql://inventory-test-mhdddforai.aws-ap-south-1.turso.io".into()),state:Value::Null,snapshot})).unwrap_or(Saved{url:None,state:Value::Null,snapshot:Snapshot{products:vec![],sale_lines:vec![],entries:vec![],updated_at:String::new()}});
  if let Some(c)=&config{if saved.url.as_ref()!=Some(&c.url){saved=Saved{url:Some(c.url.clone()),state:Value::Null,snapshot:Snapshot{products:vec![],sale_lines:vec![],entries:vec![],updated_at:String::new()}};}}
  if !directory.join("snapshot.json").exists()&&!saved.snapshot.products.is_empty(){let bytes=serde_json::to_vec(&saved).map_err(|_|"Invalid bundled display backup.")?;let backups=directory.join("backups");fs::create_dir_all(&backups).map_err(|_|"Cannot initialize automatic local backups.")?;atomic(&backups.join(format!("limited-{:x}.json",Sha256::digest(&bytes))),&bytes)?;atomic(&directory.join("snapshot.json"),&bytes)?;}
  Ok(Self{client:Client::builder().timeout(Duration::from_secs(90)).connect_timeout(Duration::from_secs(5)).redirect(Policy::none()).build().map_err(|_|"Cannot initialize the read-only connection.")?,config,directory:directory.into(),saved,verified:None,warning:String::new()})
 }
 pub fn status(&self)->Value{json!({"configured":self.config.is_some(),"connected":self.verified.is_some_and(|t|t.elapsed()<Duration::from_secs(20)),"url":self.config.as_ref().map(|c|&c.url),"updated_at":self.saved.snapshot.updated_at,"warning":self.warning,"read_only":true,"version":env!("CARGO_PKG_VERSION")})}
 pub fn view(&self)->Value{let mut result=serde_json::to_value(&self.saved.snapshot).unwrap();result["connection"]=self.status();result}
 pub fn dispatch(&mut self,action:&str,payload:&Value)->Result<Value,String>{match action{"snapshot"=>self.refresh(),"cached_snapshot"=>Ok(self.view()),"connection_status"=>Ok(self.status()),"connection_configure"=>self.configure(payload),_=>Err("Limited Access is read-only. This operation is not available.".into())}}
 fn configure(&mut self,payload:&Value)->Result<Value,String>{let url=payload["url"].as_str().ok_or("Enter the existing database URL.")?;let address=endpoint(url)?;let token=payload["token"].as_str().unwrap_or("").trim();if token.len()<32||token.len()>4096||token.chars().any(char::is_whitespace){return Err("Copy the complete existing database token without spaces or quotes.".into());}
  let remote=read(&self.client,&address,token,&[STATE_SQL])?;state(&remote[0])?;
  let config=Configuration{url:url.trim().to_string(),credential_id:Uuid::new_v4().to_string()};let entry=keyring::Entry::new(SERVICE,&config.credential_id).map_err(|_|"Secure credential storage unavailable.")?;entry.set_password(token).map_err(|_|"Cannot save the database key securely.")?;
  if let Err(error)=atomic(&self.directory.join("connection.json"),&serde_json::to_vec(&config).unwrap()){let _=entry.delete_credential();return Err(error);}
  // Do not display a previous database's saved data after an owner switches URL.
  if self.saved.url.as_deref().is_some_and(|old|old!=config.url){self.saved=Saved{url:Some(config.url.clone()),state:Value::Null,snapshot:Snapshot{products:vec![],sale_lines:vec![],entries:vec![],updated_at:String::new()}};}
  self.config=Some(config);self.verified=None;Ok(self.status())
 }
 pub fn refresh(&mut self)->Result<Value,String>{
  let result=(||->Result<(),String>{let config=self.config.as_ref().ok_or("Connection setup required. Showing the bundled read-only backup.")?;let url=endpoint(&config.url)?;let token=credential(config)?;
   let remote=read(&self.client,&url,&token,&[STATE_SQL])?;let remote=state(&remote[0])?;
   if self.saved.url.as_ref()==Some(&config.url)&&self.saved.state==remote{self.verified=Some(Instant::now());self.warning.clear();return Ok(());}
   let records=read(&self.client,&url,&token,&["BEGIN",PRODUCTS_SQL,LINES_SQL,ENTRIES_SQL,STATE_SQL,"COMMIT"])?;
   let snapshot=Snapshot{products:projected(&records[1],&["id","item_code","name","model_description","quantity"] )?,sale_lines:projected(&records[2],&["id","product_id","created_at","cr_number","product_name","item_code","model_description","quantity","unit_price_baisa","purpose","original_cr"] )?,entries:projected(&records[3],&["id","product_id","item_code","product_name","created_at","quantity","remaining_quantity"] )?,updated_at:chrono::Utc::now().to_rfc3339()};
   let saved=Saved{url:Some(config.url.clone()),state:state(&records[4])?,snapshot};let bytes=serde_json::to_vec(&saved).map_err(|_|"Cannot prepare the read-only snapshot.")?;
   let backup=self.directory.join("backups");fs::create_dir_all(&backup).map_err(|_|"Cannot create the automatic backup folder.")?;
   let hash=format!("{:x}",Sha256::digest(&bytes));let path=backup.join(format!("limited-{hash}.json"));if !path.exists(){atomic(&path,&bytes)?;}
   atomic(&self.directory.join("snapshot.json"),&bytes)?;self.saved=saved;self.verified=Some(Instant::now());self.warning.clear();prune(&backup);Ok(())})();
  if let Err(message)=result{self.verified=None;self.warning=message;}Ok(self.view())
 }
}
fn prune(folder:&Path){if let Ok(files)=fs::read_dir(folder){let mut owned=files.filter_map(Result::ok).filter(|f|{let n=f.file_name();let n=n.to_string_lossy();n.strip_prefix("limited-").and_then(|s|s.strip_suffix(".json")).is_some_and(|h|h.len()==64&&h.bytes().all(|b|b.is_ascii_hexdigit()))}).filter_map(|f|f.metadata().ok().and_then(|m|m.modified().ok()).map(|time|(time,f.path()))).collect::<Vec<_>>();owned.sort_by_key(|(t,_)|std::cmp::Reverse(*t));for (_,path) in owned.into_iter().skip(30){let _=fs::remove_file(path);}}}
#[cfg(test)]mod tests{use super::*;
 #[test]fn every_inventory_write_and_ai_export_restore_is_rejected(){let d=tempfile::tempdir().unwrap();let mut b=Backend::open(d.path(),&d.path().join("missing")).unwrap();for action in ["stock_entry","stock_out","save_product","edit_record","delete_record","restore","backup","warranty","damaged_return","assistant_chat","voice_start","save_pdf","save_excel","sql","execute"]{assert!(b.dispatch(action,&json!({})).unwrap_err().contains("read-only"),"{action}");}}
 #[test]fn saved_data_cannot_contain_hidden_fields(){assert!(serde_json::from_value::<Product>(json!({"id":"a","item_code":"1","name":"Screen","model_description":"S3","quantity":2,"cost_baisa":123})).is_err());assert!(!PRODUCTS_SQL.contains("unit_cost"));assert!(!LINES_SQL.contains("cost_baisa"));assert!(!LINES_SQL.contains("profit"));assert!(!LINES_SQL.contains("record_json FROM"));}
 #[test]fn sql_writes_are_rejected_before_any_network_call(){let c=Client::new();for query in ["DELETE FROM products","UPDATE sales SET cr_number=1","INSERT INTO products VALUES(1)","PRAGMA writable_schema=ON","SELECT * FROM sales"]{assert!(read(&c,"https://does-not-exist.turso.io","unused",&[query]).unwrap_err().contains("fixed read-only"));}}
 #[test]fn endpoints_cannot_redirect_keys_to_other_hosts(){for u in ["http://inventory.turso.io","https://evil.test","https://inventory.turso.io/other","https://user:pass@inventory.turso.io"]{assert!(endpoint(u).is_err());}assert!(endpoint("libsql://inventory.turso.io").is_ok());}
 #[test]fn bundled_backup_is_readable_without_a_cloud_write(){let d=tempfile::tempdir().unwrap();let seed=d.path().join("seed.json");fs::write(&seed,serde_json::to_vec(&Snapshot{products:vec![Product{id:"1".into(),item_code:"1".into(),name:"شاشة".into(),model_description:"Screen".into(),quantity:2}],sale_lines:vec![],entries:vec![],updated_at:"2026-11-22".into()}).unwrap()).unwrap();let mut b=Backend::open(d.path(),&seed).unwrap();let s=b.dispatch("snapshot",&json!({})).unwrap();assert_eq!(s["products"][0]["quantity"],2);assert_eq!(s["connection"]["read_only"],true);assert_eq!(s["connection"]["connected"],false);assert!(!d.path().join("connection.json").exists());}
}
